#!/bin/bash
# mk.sh <src MES.Web> <dest dir> <port>  — dựng harness chạy cả MES.Web trên EF giả
set -e
SRC="$1"; DST="$2"; PORT="$3"
H="$(cd "$(dirname "$0")" && pwd)"
TOOLS="$H/../GiaoNhanFuzz"
rm -rf "$DST"; mkdir -p "$DST"
cp -r "$SRC/." "$DST/"; rm -rf "$DST/bin" "$DST/obj" "$DST/Data/AppDbContext - Copy.bak"
rm -f "$DST/Services/PmSaveLockSql.cs"
# [G32-SAOLUU 22/11] sao lưu: SaoLuuSql thật dùng Microsoft.Data.SqlClient → harness thay bằng bản giả (chỉ khi nguồn có Gói 32a)
if [ -f "$SRC/Services/SaoLuuSql.cs" ]; then rm -f "$DST/Services/SaoLuuSql.cs"; mkdir -p "$DST/Stubs"; cp "$H/Stubs/HarnessSaoLuu.cs" "$DST/Stubs/"; fi   # [S8D-KHOA 07/11] khoá lượt lưu PM trên kết nối SQL riêng (Microsoft.Data.SqlClient) — harness EF giả dùng cách cũ
mkdir -p "$DST/Stubs"
cp "$TOOLS/EfStub.cs" "$TOOLS/EfCompile2.cs" "$DST/Stubs/"
# [KHO-5 02/11] ClosedXML tối thiểu ghi .xlsx thật (thay XlStub chỉ-để-biên-dịch) — drive_kho.py đọc file Excel trang Kho xuất ra
cp "$H/Stubs/XlMini.cs" "$DST/Stubs/"
cp "$H/Stubs/WebStub.cs" "$H/Stubs/HarnessFixup.cs" "$H/Stubs/HarnessSeed.cs" "$H/Stubs/HarnessLedger.cs" "$H/Stubs/HarnessFail.cs" "$H/Stubs/HarnessN3f.cs" "$H/Stubs/HarnessSua.cs" "$H/Stubs/HarnessG13.cs" "$H/Stubs/HarnessG15.cs" "$H/Stubs/HarnessG16.cs" "$H/Stubs/HarnessG14Seed.cs" "$H/Stubs/HarnessKtt.cs" "$H/Stubs/HarnessG19.cs" "$H/Stubs/HarnessG20.cs" "$H/Stubs/HarnessG21.cs" "$H/Stubs/HarnessG23.cs" "$H/Stubs/HarnessG24.cs" "$H/Stubs/HarnessG25.cs" "$H/Stubs/HarnessG27.cs" "$H/Stubs/HarnessNho.cs" "$H/Stubs/HarnessG28.cs" "$H/Stubs/HarnessG29.cs" "$H/Stubs/HarnessP03.cs" "$H/Stubs/HarnessN21.cs" "$H/Stubs/HarnessN22.cs" "$DST/Stubs/"   # [KHO-TARO-THANG 12/11] HarnessKtt = dữ liệu KH-KTT (drive_ktt.py) · [LS-THOIGIAN 12/11] HarnessG19 = dữ liệu KH-G19 (drive_g19.py)
